script:
// Récupérer la date du jour
var dateDuJour = new Date();

// Obtenir les composants de la date
var jour = dateDuJour.getDate();
var mois = dateDuJour.getMonth() + 1; // Les mois commencent à 0, donc ajout de 1
var annee = dateDuJour.getFullYear();
var title = frappe.session.user_fullname;

// Formater la date
var dateFormatee = jour + '/' + mois + '/' + annee;

// Récupérer l'élément avec la classe "some-class" dans le framework Frappe
var someClassElement = root_element.querySelector('.some-class');
var nom = root_element.querySelector('.nom');

// Mettre à jour le contenu de l'élément avec la date formatée

nom.innerHTML = "Bonjour <strong>" + title + "</strong>";
someClassElement.innerHTML = dateFormatee;

frappe.call({
    method: "frappe.client.get",
    args: {
        doctype: "User",
        name: frappe.session.user, // Récupérer l'utilisateur connecté
    },
    callback(r) {
        if (r.message) {
            const userImageContainer = root_element.querySelector('.user-image-container');
            const userImageElement = root_element.querySelector('#imageUser');

            // Supprimer les enfants existants (au cas où)
            userImageContainer.innerHTML = "";

            // Récupérer l'image de l'utilisateur
            var userImageURL = r.message.user_image;

            // Vérifier si l'image existe
            if (userImageURL) {
                // Afficher l'image utilisateur
                userImageElement.src = userImageURL;
                userImageElement.style.display = "block";
                userImageContainer.appendChild(userImageElement);
            } else {
                // Générer un avatar avec les initiales
                const fullName = r.message.full_name || frappe.session.user_fullname || "Utilisateur";
                const initials = fullName.split(" ").map(word => word[0]).join("").slice(0, 2);

                // Créer l'élément avatar
                const avatarElement = document.createElement("div");
                avatarElement.className = "user-avatar";
                avatarElement.innerText = initials;

                userImageContainer.appendChild(avatarElement);
            }
        }
    }
});

style:
/* Conteneur principal */
.header-container {
  display: flex;
  flex-wrap: wrap; /* Permet aux éléments de passer à la ligne si nécessaire */
  align-items: center; /* Aligne les éléments verticalement au centre */
  background-color: #ffffff; /* Fond blanc */
  padding: 1rem; /* Espacement interne */
  border-radius: 0.75rem; /* Coins arrondis */
  border: 0.5px solid #e5e7eb; /* Bordure grise très fine */
  width: 100%;
  gap: 1rem; /* Espacement entre les sections */
  box-sizing: border-box; /* Inclut le padding dans la largeur totale */
}

/* Conteneur de l'image utilisateur */
.user-image-container {
  flex: 0 0 auto; /* Ne s'étire pas */
  width: 3rem; /* Taille ajustée */
  height: 3rem;
  border-radius: 50%;
  overflow: hidden;
  border: 0.5px solid #e5e7eb;
  display: flex;
  justify-content: center;
  align-items: center;
}

/* Image utilisateur */
.user-image {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

/* Avatar utilisateur */
.user-avatar {
  width: 3rem;
  height: 3rem;
  border-radius: 50%;
  background-color: #457b9d;
  color: #ffffff;
  display: flex;
  justify-content: center;
  align-items: center;
  font-size: 1rem;
  font-weight: 600;
  text-transform: uppercase;
}

/* Contenu textuel */
.text-content {
  flex: 1; /* Prend tout l'espace restant */
  display: flex;
  flex-direction: column; /* Affiche le texte en colonne */
  justify-content: center;
  text-align: left; /* Aligne le texte à gauche */
  gap: 0.2rem; /* Réduction de l'espacement entre les lignes */
}

.title {
  font-size: 1rem; /* Taille réduite */
  font-weight: 600; /* Gras */
  color: #1f2937; /* Couleur sombre */
  margin: 0;
}

.subtitle {
  font-size: 0.8rem;
  font-weight: 400;
  color: #6b7280;
  margin: 0;
}

/* Contenu de la date */
.date-content {
  flex: 0 0 auto; /* Ne s'étire pas */
  display: flex;
  align-items: center;
  gap: 0.5rem;
  margin-left: auto;
}

.date {
  font-size: 0.8rem;
  font-weight: 400;
  color: #1f2937;
  margin: 0;
  white-space: nowrap;
}

/* Icône */
.icon {
  width: 1.5rem;
  height: 1.5rem;
  display: flex;
  justify-content: center;
  align-items: center;
  background-color: #f3f4f6;
  border-radius: 50%;
  color: #1f2937;
}

/* Média queries */
@media (max-width: 768px) {
  .header-container {
    flex-wrap: nowrap; /* Empêche les éléments de passer à la ligne */
    text-align: left; /* Texte aligné à gauche */
    gap: 1rem; /* Espacement suffisant entre les sections */
  }

  .text-content {
    text-align: left; /* Aligne toujours le texte à gauche */
  }

  .date-content {
    margin-left: auto; /* Place la date à l'extrémité droite */
  }
}

@media (max-width: 480px) {
  .header-container {
    flex-direction: column; /* Sur très petits écrans, tout passe en colonne */
    align-items: flex-start; /* Aligne les éléments à gauche */
  }

  .text-content {
    text-align: left; /* Assure que le texte reste aligné à gauche */
    gap: 0.5rem; /* Espacement réduit entre le titre et le sous-titre */
  }

  .date-content {
    margin-left: 0; /* Supprime l'espacement gauche */
    justify-content: flex-start; /* Aligne la date à gauche */
  }
}

script:
// Vérifie si root_element est disponible
if (root_element) {

  const processCards = (container) => {
    const cards = container.querySelectorAll(".home-card");
    if (!cards.length) return false;

    // On se contente de parcourir les cartes
    cards.forEach(card => {
      const title = card.querySelector(".card-title");
      if (!title) return;

      // Sécurité : si un badge existe déjà, on le supprime
      const badge = title.querySelector(".badge");
      if (badge) {
        badge.remove();
      }
    });

    return true;
  };

  if (!processCards(root_element)) {
    const obs = new MutationObserver((mutations, observer) => {
      if (processCards(root_element)) {
        observer.disconnect();
      }
    });

    obs.observe(root_element, { childList: true, subtree: true });

    setTimeout(() => {
      processCards(root_element);
      obs.disconnect();
    }, 3000);
  }

} else {
  console.error("Erreur Bloc HTML Personnalisé : 'root_element' n'a pas été trouvé.");
}

style:
/* 
  Container principal :
  - 4 colonnes par défaut (grands écrans)
  - 2 colonnes si < 1024px
  - 1 colonne si < 768px
*/
.home-cards-container {
  width: 100%;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1rem;
  font-family: "Inter", sans-serif;
}

/* Si vous voulez cibler spécifiquement le deuxième conteneur : */
/* .home-cards-container:nth-of-type(2) {
  grid-template-columns: repeat(4, 1fr);
} */

/* Force chaque carte à remplir sa colonne */
.home-cards-container .home-card {
  width: 100%;
  box-sizing: border-box;
}

/* Carte individuelle */
.home-card {
  border: 1px solid var(--gray-200, #e5e7eb);
  border-radius: 0.5rem;
  display: flex;
  align-items: center;
  gap: 1rem;
  padding: 0.5rem 1rem;
  background-color: #fff;
}

/* Titre */
.card-title {
  font-size: 0.7rem;
  font-weight: 500;
  margin: 0;
}

/* Cercle (pour l'icône) */
.icon-circle {
  width: 1.6rem;
  height: 1.6rem;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 0.5rem;
  color: var(--gray-800, #1f2937);
  font-size: 0.8rem;
}

/* Boutons alignés à droite dans la carte */
.card-actions {
  margin-left: auto;
  display: flex;
  gap: 0.5rem;
}

/* Boutons (même taille que le cercle) */
.action-btn {
  width: 1.6rem;
  height: 1.6rem;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--gray-200, #e5e7eb);
  border-radius: 0.5rem;
  cursor: pointer;
  color: var(--gray-700, #374151);
  transition: background-color 0.2s;
  font-size: 1rem;
  line-height: 1;
  background: #fff;
}

.action-btn:hover {
  background-color: var(--gray-100, #f3f4f6);
}

/* TABLETTE : < 1024px => 2 colonnes */
@media (max-width: 1024px) {
  .home-cards-container {
    grid-template-columns: repeat(2, 1fr);
  }
}

/* MOBILE : < 768px => 1 colonne */
@media (max-width: 768px) {
  .home-cards-container {
    grid-template-columns: 1fr;
  }
}

.badge {
  display: inline-block;
  padding: 0.2em 0.6em;
  font-size: 0.9em;
  font-weight: 500;
  border-radius: 0.25rem;
  color: #fff;
}
.badge-info    { background-color: #3b82f6; }
.badge-success { background-color: #10b981; }
.badge-warning { background-color: #f59e0b; }
.badge-danger  { background-color: #ef4444; }

.badge-custom-count {
  background-color: #e7f1ff; /* Un bleu très clair, similaire à l'image */
  color: #0a58ca; /* Couleur de texte contrastée (bleu foncé) */
  padding: 0.3em 0.5em; /* Ajustement léger du padding si nécessaire */
  font-weight: 600; /* Rendre le texte un peu plus gras */
  vertical-align: middle; /* Meilleur alignement vertical avec le titre */
}
